SELECT COALESCE(count(`id`), 0 ) `num`, DATE_FORMAT(`data_time`,${dateFormat}) `timeFlag` FROM `emergency_phone_number`
and `data_time` >= #{st}
and `data_time` <= #{et}
GROUP BY DATE_FORMAT(`data_time`, ${dateFormat})

SELECT COALESCE(count(`id`), 0 ) `num`, DATE_FORMAT(`data_time`,${dateFormat}) `timeFlag` FROM `emergency_phone_number`
and `data_time` >= #{st}
and `data_time` <= #{et}
GROUP BY DATE_FORMAT(`data_time`, ${dateFormat})

SELECT COALESCE(count(`id`), 0 ) `num`, to_char(`data_time`,${dateFormat}) `timeFlag` FROM `emergency_phone_number`
and `data_time` >= #{st}
and `data_time` <= #{et}
GROUP BY to_char(`data_time`, ${dateFormat})

SELECT a.`id` `id`, a.`record_id` `recordId`, a.`file_url` `fileUrl`, b.`code` `deviceCode`, b.`area_name` `areaName`, a.`data_time` `dataTime` FROM `emergency_phone_number` a LEFT JOIN `security_device` b ON a.`device_id` = b.`third_party_id`
and a.`data_time` >= #{st}
and a.`data_time` <= #{et}
order by a.`data_time` DESC
